package com.clanhub;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The drop rates of the Old School RuneScape Wiki, from the table the plugin bundles
 * ({@code /com/clanhub/drops.json}, built from the wiki's drop data and credited in its own header): for an item's name,
 * the sources it drops from, the most likely first. The table is read once, off the client thread, a second or two
 * after start-up; until then, and for ever if the file is missing or unreadable, every lookup answers an empty list and
 * the item card simply shows no Drop row. Parsing is pure and is the only part that needs the table's shape.
 *
 * <p>Choice: the load task runs once; a plugin restart runs it again.
 */
final class DropRates
{
	private static final Logger log = LoggerFactory.getLogger(DropRates.class);

	/** Where the bundled table lives on the classpath. */
	private static final String RESOURCE = "/com/clanhub/drops.json";

	/** One place an item drops from, with how often. */
	static final class DropSource
	{
		/** The source's name, such as "Abyssal demon" or "Chambers of Xeric". */
		final String from;
		/** The rate as the wiki writes it, such as "1/512", "1/171.6" or "Rare". */
		final String rate;
		/** The wiki page of the source, such as "Abyssal_demon". */
		final String wiki;

		DropSource(String from, String rate, String wiki)
		{
			this.from = from;
			this.rate = rate;
			this.wiki = wiki;
		}
	}

	/** A table read whole: the sources by the item's exact name, and by its name ignoring case. */
	private static final class Table
	{
		private final Map<String, List<DropSource>> exact = new HashMap<>();
		private final Map<String, List<DropSource>> ignoringCase = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
	}

	/** The table once loaded; null until the load has published it. */
	private volatile Table table;

	/** A table that has not loaded: every lookup answers nothing and {@link #loaded()} is false. */
	DropRates()
	{
	}

	private DropRates(Table table)
	{
		this.table = table;
	}

	/**
	 * Reads the table's shape: {@code {"items": {"<item name>": [{"from": "...", "rate": "...", "wiki": "..."}]}}}.
	 * A missing or empty {@code items} gives an empty table that counts as loaded.
	 *
	 * <p>Choice: a source with no {@code from} or no {@code rate} is skipped, an item left with no source is left out,
	 * and a missing {@code wiki} reads as an empty text; nothing in the file's shape that is merely odd stops the rest
	 * of the table being read.
	 *
	 * @throws com.google.gson.JsonParseException when the text is not JSON
	 */
	static DropRates parse(Reader json, Gson gson)
	{
		final Table read = new Table();
		final JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root != null && root.has("items") && root.get("items").isJsonObject())
		{
			for (final Map.Entry<String, JsonElement> item : root.getAsJsonObject("items").entrySet())
			{
				final List<DropSource> sources = sourcesOf(item.getValue());
				if (!sources.isEmpty())
				{
					final List<DropSource> kept = Collections.unmodifiableList(sources);
					read.exact.put(item.getKey(), kept);
					read.ignoringCase.putIfAbsent(item.getKey(), kept);
				}
			}
		}
		return new DropRates(read);
	}

	/** The sources one item's array holds, the file's order kept. */
	private static List<DropSource> sourcesOf(JsonElement array)
	{
		final List<DropSource> sources = new ArrayList<>();
		if (!array.isJsonArray())
		{
			return sources;
		}
		for (final JsonElement entry : array.getAsJsonArray())
		{
			if (!entry.isJsonObject())
			{
				continue;
			}
			final JsonObject source = entry.getAsJsonObject();
			final String from = text(source, "from");
			final String rate = text(source, "rate");
			if (!from.isEmpty() && !rate.isEmpty())
			{
				sources.add(new DropSource(from, rate, text(source, "wiki")));
			}
		}
		return sources;
	}

	/** The text of a member, or an empty text when it is missing or is not a string. */
	private static String text(JsonObject object, String member)
	{
		final JsonElement value = object.get(member);
		return value != null && value.isJsonPrimitive() ? value.getAsString() : "";
	}

	/**
	 * The sources the item drops from, the most likely first: those of the exact name, else of the name ignoring case,
	 * else an empty list. Also an empty list while the table has not loaded.
	 */
	List<DropSource> lookup(String itemName)
	{
		final Table loaded = table;
		if (loaded == null || itemName == null)
		{
			return Collections.emptyList();
		}
		final List<DropSource> exact = loaded.exact.get(itemName);
		if (exact != null)
		{
			return exact;
		}
		final List<DropSource> similar = loaded.ignoringCase.get(itemName);
		return similar != null ? similar : Collections.<DropSource>emptyList();
	}

	/** Whether the table has been read and published. */
	boolean loaded()
	{
		return table != null;
	}

	/**
	 * Reads the bundled table on the executor and publishes it. A missing resource or a table that does not parse leaves
	 * this empty and logs one warning naming the cause; nothing is thrown out of the task.
	 *
	 * <p>Choice: after a failed load {@link #loaded()} stays false, since nothing was published.
	 */
	void loadInBackground(ScheduledExecutorService executor, Gson gson)
	{
		executor.execute(() -> load(gson));
	}

	/** The load task: one classpath read, one parse, one publish. */
	private void load(Gson gson)
	{
		try (InputStream in = DropRates.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("The drop rate table {} is not in the plugin; the cards show no drop rates", RESOURCE);
				return;
			}
			table = parse(new InputStreamReader(in, StandardCharsets.UTF_8), gson).table;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("The drop rate table {} could not be read ({}); the cards show no drop rates", RESOURCE, e.toString());
		}
	}
}

package com.clanhub;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * The 2hBuilds settings icon, drawn in code: a ring with eight teeth and a hole through the middle, the picture the
 * settings icon of every 2hBuilds plugin shows (STANDARD A4). It is the bank's icon, pulled out of its widget helper so
 * the one picture can be copied into another plugin unchanged; it refers to no class of the plugin it sits in.
 *
 * <p>The ring is a stroke and not a filled disc, so the middle stays transparent and the picture reads as a settings
 * icon at 12 px rather than as a cogged blob. The teeth are eight round-capped spokes every 45 degrees, starting on
 * the ring's own circle so each is rooted in the ring's metal and none reaches into the hole. Every length is a
 * fraction of the size, so the same shape comes out at any size.
 */
final class GearGlyph
{
	/** The number of teeth. */
	static final int TEETH = 8;
	/** The smallest side drawn: below it the hole closes and the teeth merge. */
	static final int MIN_SIZE = 7;

	private GearGlyph()
	{
	}

	/**
	 * A new square icon, transparent except for the ring and its teeth.
	 *
	 * @param size   the icon's side in px; anything under {@value #MIN_SIZE} is raised to it
	 * @param colour the ink; null falls back to the sidebar's quiet grey, {@link ColorScheme#LIGHT_GRAY_COLOR}
	 */
	static ImageIcon icon(int size, Color colour)
	{
		final int s = Math.max(MIN_SIZE, size);
		final BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setColor(colour == null ? ColorScheme.LIGHT_GRAY_COLOR : colour);
			final double centre = s / 2.0;
			// The ring's centre line, the width of its metal, and how far a tooth's centre line reaches - the last
			// one pulled in by half a tooth so the round cap lands inside the icon instead of being clipped.
			final double ring = centre * 0.52;
			final float ringWidth = (float) Math.max(1.5, s * 0.2);
			final float toothWidth = (float) Math.max(1.3, s * 0.16);
			final double toothOut = centre - toothWidth / 2.0 - 0.25;
			g.setStroke(new BasicStroke(ringWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Ellipse2D.Double(centre - ring, centre - ring, ring * 2.0, ring * 2.0));
			g.setStroke(new BasicStroke(toothWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			for (int i = 0; i < TEETH; i++)
			{
				final double angle = i * 2.0 * Math.PI / TEETH;
				final double cos = Math.cos(angle);
				final double sin = Math.sin(angle);
				g.draw(new Line2D.Double(centre + cos * ring, centre + sin * ring,
					centre + cos * toothOut, centre + sin * toothOut));
			}
		}
		finally
		{
			g.dispose();
		}
		return new ImageIcon(img);
	}
}

package com.clanhub;

import java.util.List;

/**
 * What the overlay, the painter and the menu need of any card: the words it shows, the line it came from with the
 * place of its words in that line, and its picture. The item card is one; the cards of later lots (quests, kinds of
 * broadcast, drop rates) are others. Pure model: it holds words and numbers and asks the client nothing.
 */
interface HoverCard
{
	/** One label with its value, and a note that follows the value in the label's grey. */
	final class Pair
	{
		/** The label, such as "Price". */
		final String label;
		/** The value, such as "121M". */
		final String value;
		/** What follows the value in the label's grey, such as " (460 each)"; empty when there is none. */
		final String note;

		Pair(String label, String value, String note)
		{
			this.label = label;
			this.value = value;
			this.note = note;
		}
	}

	/** The card's title, in bold at the top. */
	String title();

	/** The card's rows of label and value pairs, under the title; may be empty. */
	List<List<Pair>> rows();

	/**
	 * The description lines a card that is not an item's shows under its rows, already wrapped, one line each; empty for
	 * an item.
	 */
	List<String> notes();

	/** The card's last line: what a right-click does. */
	String hint();

	/** The wiki address "Open wiki" opens. */
	String wikiUrl();

	/**
	 * The title of the wiki page whose first paragraph the card shows under its rows: the name an item is called by, or
	 * a page's name with its underscores read as spaces; what is asked of the wiki, and the only thing that is.
	 */
	String wikiTitle();

	/** The chat line as plain text, what "Copy" puts on the clipboard. */
	String plainLine();

	/** Where the card's words start in {@link #plainLine()}. */
	int start();

	/** Just past the card's last word in {@link #plainLine()}. */
	int end();

	/** The id of the item whose sprite is the card's picture, or -1 when the picture is not an item's. */
	int itemId();

	/** How many of the item the picture shows; 1 when the card has no item. */
	int quantity();

	/** The game's own sprite id for the picture when it is not an item's, or -1. */
	int spriteId();

	/**
	 * Whether the card's words are coloured in the chat at rest. A card that is not marked is quiet: the line keeps the
	 * game's own colour, and the words show themselves only when the mouse is on the line, or under the "Always underline
	 * level-ups" setting.
	 */
	boolean marked();
}

package com.clanhub;

import java.net.URLDecoder;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * What the card says about one thing a broadcast line names that is not an item: a quest, a combat achievement task, a
 * pet, a level, a diary tier, a personal best or a kill count. Pure model: it holds the title, one row of facts, the
 * notes (the description, whole), the wiki page, and the line it came from with the place of the thing's name in it; it draws
 * nothing and asks the client nothing. It is the {@link HoverCard} of these: a game sprite for its picture, or an item
 * (a pet's, the clue watch's), or none.
 */
final class InfoCard implements HoverCard
{
	/** The card's last line, the item card's. */
	private static final String HINT = "Right-click: Open wiki | Copy";
	/** The wiki's address for a page, to which the page's name is added. */
	private static final String WIKI = "https://oldschool.runescape.wiki/w/";

	private final String title;
	private final List<List<Pair>> rows;
	private final List<String> notes;
	private final String page;
	private final String line;
	private final int start;
	private final int end;
	private final int spriteId;
	private final int itemId;
	private final boolean marked;

	/**
	 * The card with its title, its one row of facts, its notes (the description or the sentences of it, whole, for the
	 * painter to wrap; may be empty), the wiki page to open (the part after {@code /w/}), the plain chat line, where the
	 * thing's name starts and ends in that line, and the game sprite of its picture or -1 for none; the card has no item
	 * for a picture.
	 */
	InfoCard(String title, List<Pair> row, List<String> notes, String page, String line, int start, int end,
		int spriteId)
	{
		this(title, row, notes, page, line, start, end, spriteId, -1);
	}

	/**
	 * The same card with an item for its picture: {@code itemId} is the id of the item whose sprite it shows (a pet's, the
	 * clue watch's), or -1 for none.
	 */
	InfoCard(String title, List<Pair> row, List<String> notes, String page, String line, int start, int end,
		int spriteId, int itemId)
	{
		this(title, row, notes, page, line, start, end, spriteId, itemId, true);
	}

	/**
	 * The same card with {@code marked} said: false makes it a quiet one, whose words the chat does not colour (the level,
	 * total level and XP phrases); the other constructors make a marked card.
	 */
	InfoCard(String title, List<Pair> row, List<String> notes, String page, String line, int start, int end,
		int spriteId, int itemId, boolean marked)
	{
		this.marked = marked;
		this.itemId = itemId;
		this.title = title;
		this.rows = Collections.singletonList(Collections.unmodifiableList(new ArrayList<>(row)));
		this.notes = Collections.unmodifiableList(new ArrayList<>(notes));
		this.page = page;
		this.line = line;
		this.start = start;
		this.end = end;
		this.spriteId = spriteId;
	}

	/**
	 * The wiki page for a name: spaces as underscores, then percent-encoded as UTF-8 so an apostrophe, an ampersand or a
	 * bracket reaches the wiki whole ("Lumbridge & Draynor Diary" is "Lumbridge_%26_Draynor_Diary"); a dot is left as it
	 * is, as the wiki's own addresses leave it.
	 */
	static String pageFor(String name)
	{
		return URLEncoder.encode(name.replace(' ', '_'), StandardCharsets.UTF_8).replace("+", "%20");
	}

	/** The card's title. */
	@Override
	public String title()
	{
		return title;
	}

	/** The card's one row of facts. */
	@Override
	public List<List<Pair>> rows()
	{
		return rows;
	}

	/** The notes under the row, whole sentences the painter wraps to the card; empty for most kinds. */
	@Override
	public List<String> notes()
	{
		return notes;
	}

	/** The card's last line: what a right-click does, the same as the item card's. */
	@Override
	public String hint()
	{
		return HINT;
	}

	/** The wiki's page for the thing the card is about. */
	@Override
	public String wikiUrl()
	{
		return WIKI + page;
	}

	/**
	 * The wiki page's title for the card's paragraph: the page with its percent-encoding undone and its underscores read
	 * as spaces ("Dragon_Slayer_II" is "Dragon Slayer II", "Why_Cook%3F" is "Why Cook?").
	 *
	 * <p>Choice: a page whose percent-encoding is malformed keeps it as written, with its underscores read as spaces.
	 */
	@Override
	public String wikiTitle()
	{
		try
		{
			return URLDecoder.decode(page, StandardCharsets.UTF_8).replace('_', ' ');
		}
		catch (IllegalArgumentException e)
		{
			return page.replace('_', ' ');
		}
	}

	/** The chat line as plain text, what "Copy" puts on the clipboard. */
	@Override
	public String plainLine()
	{
		return line;
	}

	/** Where the thing's name starts in the line. */
	@Override
	public int start()
	{
		return start;
	}

	/** Just past the thing's name in the line. */
	@Override
	public int end()
	{
		return end;
	}

	/** The id of the item whose sprite is the card's picture (a pet's, the clue watch's), or -1 when it has none. */
	@Override
	public int itemId()
	{
		return itemId;
	}

	/** No item, so no stack: 1. */
	@Override
	public int quantity()
	{
		return 1;
	}

	/** The game sprite of the card's picture, or -1 when it has none. */
	@Override
	public int spriteId()
	{
		return spriteId;
	}

	/** Whether the card's words are coloured in the chat; false for the quiet level, total level and XP cards. */
	@Override
	public boolean marked()
	{
		return marked;
	}
}

package com.clanhub;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.util.QuantityFormatter;

/**
 * What the card says about one item named in a chat line: the item, how many, its prices, and the line it came from
 * with the place of the name in it. Pure model: it holds numbers and words and makes the card's texts and the wiki
 * address; it draws nothing and asks the client nothing. It is the {@link HoverCard} of an item: no notes, and the
 * item's own sprite for its picture.
 */
final class ItemCard implements HoverCard
{
	/** The card's last line. */
	private static final String HINT = "Right-click: Open wiki | Copy";
	/** The wiki's item lookup, to which the id and the name are added. */
	private static final String WIKI_LOOKUP = "https://oldschool.runescape.wiki/w/Special:Lookup?type=item&id=";
	/** What a price or an alch value of nothing reads as. */
	private static final String NONE = "-";
	/** How many drop sources a card shows at most; the rest are counted in the "and N more" row. */
	private static final int MAX_DROPS = 4;

	/** The item's id. */
	final int id;
	/** The item's name. */
	final String name;
	/** How many of the item the line names. */
	final int quantity;
	/** The market price of one, in coins; 0 when the item has none. */
	final long price;
	/** The high alchemy value of one, in coins. */
	final int alch;
	/** The chat line without its tags. */
	final String line;
	/** Where the name starts in {@link #line}. */
	final int start;
	/** Just past the name's last character in {@link #line}. */
	final int end;
	/** The drop sources the card shows, the table's first four in its order; empty when the table has none. */
	private final List<DropRates.DropSource> drops;
	/** How many sources the table holds beyond the ones shown. */
	private final int more;

	ItemCard(int id, String name, int quantity, long price, int alch, String line, int start, int end)
	{
		this(id, name, quantity, price, alch, line, start, end, Collections.<DropRates.DropSource>emptyList());
	}

	/**
	 * The card with the item's drop sources in the table's order (the monsters first, the best rate first), or an empty
	 * list for none.
	 *
	 * <p>Choice: the card shows the table's first four sources in the table's order, none reversed, so the best monster
	 * leads; when the table holds more, {@link #rows} ends in one more row, "and N more" with N the count beyond four,
	 * a row with no rate, so either painter draws it as a grey line of its own.
	 */
	ItemCard(int id, String name, int quantity, long price, int alch, String line, int start, int end,
		List<DropRates.DropSource> drops)
	{
		this.drops = Collections.unmodifiableList(new ArrayList<>(drops.subList(0, Math.min(MAX_DROPS, drops.size()))));
		this.more = drops.size() - this.drops.size();
		this.id = id;
		this.name = name;
		this.quantity = quantity;
		this.price = price;
		this.alch = alch;
		this.line = line;
		this.start = start;
		this.end = end;
	}

	/** The card's title: the name, with "x10" after it for a stack. */
	@Override
	public String title()
	{
		return quantity > 1 ? name + " x" + quantity : name;
	}

	/**
	 * The card's rows of label and value pairs: the price and the high alch value, and under them one row for each drop
	 * source (at most four), each a single pair with the source's name as its label and the rate as its value
	 * ("Abyssal demon", "1/512"), so a painter can set the name at the left and the rate at the right; when the table
	 * holds more sources, a last row of one pair with "and 2 more" as its label and no value. For a stack the
	 * price is the total with the price of one after it, and the alch value is the total; a price of nothing reads "-".
	 */
	@Override
	public List<List<Pair>> rows()
	{
		final String each = quantity > 1 && price > 0 ? " (" + stackSize(price) + " each)" : "";
		final Pair priced = new Pair("Price", price > 0 ? stackSize(price * quantity) : NONE, each);
		final Pair alched = new Pair("High alch", alch > 0 ? stackSize((long) alch * quantity) : NONE, "");
		final List<List<Pair>> rows = new ArrayList<>();
		rows.add(Arrays.asList(priced, alched));
		for (final DropRates.DropSource source : drops)
		{
			rows.add(Collections.singletonList(new Pair(source.from, source.rate, "")));
		}
		if (more > 0)
		{
			rows.add(Collections.singletonList(new Pair("and " + more + " more", "", "")));
		}
		return rows;
	}

	/** An item has no description lines. */
	@Override
	public List<String> notes()
	{
		return Collections.emptyList();
	}

	/** The card's last line: what a right-click does. */
	@Override
	public String hint()
	{
		return HINT;
	}

	/**
	 * The wiki's lookup page for the item, by id and name.
	 *
	 * <p>Choice: the name is percent-encoded in full, a space as %20 (not +), so a name with an apostrophe or a bracket
	 * reaches the wiki whole.
	 */
	@Override
	public String wikiUrl()
	{
		return WIKI_LOOKUP + id + "&name=" + URLEncoder.encode(name, StandardCharsets.UTF_8).replace("+", "%20");
	}

	/** The wiki page's title for the card's paragraph: the item's name, which the wiki's redirects resolve. */
	@Override
	public String wikiTitle()
	{
		return name;
	}

	/** The chat line as plain text, what "Copy" puts on the clipboard. */
	@Override
	public String plainLine()
	{
		return line;
	}

	/** Where the item's name starts in the line. */
	@Override
	public int start()
	{
		return start;
	}

	/** Just past the item's name in the line. */
	@Override
	public int end()
	{
		return end;
	}

	/** The item's id: its sprite is the card's picture. */
	@Override
	public int itemId()
	{
		return id;
	}

	/** How many of the item the line names. */
	@Override
	public int quantity()
	{
		return quantity;
	}

	/** An item's picture is its item sprite, never a game sprite. */
	@Override
	public int spriteId()
	{
		return -1;
	}

	/** An item's name is coloured in the chat. */
	@Override
	public boolean marked()
	{
		return true;
	}

	/** A number the way the game writes a stack: 121M, 25.2M, 123K, 4,600. */
	private static String stackSize(long value)
	{
		return QuantityFormatter.quantityToStackSize(value);
	}
}

package com.clanhub;

import java.util.Collections;
import java.util.List;
import java.util.Locale;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;

/**
 * The one place an item card is made: it turns an item's name, with where the name sits in a chat line, into an
 * {@link ItemCard} with the item's id, its market price and its high alchemy value from the item manager, and the item's
 * drop sources from the {@link DropRates} table when it has any. The id comes from the item manager's price list, and,
 * when that does not know the name (a pet and the other untradeables have no price), from the {@link ItemNameIndex}. Every
 * item manager lookup is the item manager's, so a call belongs on the client thread, the caller's.
 */
class ItemCards
{
	private final ItemManager itemManager;
	/** The drop rate table, or null for none. */
	private final DropRates dropRates;
	/** The names of every real item, or null for none; asked when the price list does not know a name. */
	private final ItemNameIndex index;

	/** Cards without drop rates and without the names index: no table, no index. */
	ItemCards(ItemManager itemManager)
	{
		this(itemManager, null, null);
	}

	/** Cards with the drop rates of {@code dropRates}, which may still be loading, and no names index. */
	ItemCards(ItemManager itemManager, DropRates dropRates)
	{
		this(itemManager, dropRates, null);
	}

	/** Cards with the drop rates of {@code dropRates} and the names of {@code index}, either of which may still be loading. */
	ItemCards(ItemManager itemManager, DropRates dropRates, ItemNameIndex index)
	{
		this.itemManager = itemManager;
		this.dropRates = dropRates;
		this.index = index;
	}

	/**
	 * The id of the item called {@code name}: the first search result whose name equals {@code name} ignoring case (a
	 * result that only starts with it, such as "Dragon claws (or)", does not count), else the id the names index holds for
	 * the lowercase name, else -1.
	 *
	 * <p>Choice: a null name has no id.
	 */
	int idOf(String name)
	{
		if (name == null)
		{
			return -1;
		}
		for (final ItemPrice result : itemManager.search(name))
		{
			if (name.equalsIgnoreCase(result.getName()))
			{
				return result.getId();
			}
		}
		final Integer indexed = index == null ? null : index.idOf(name.toLowerCase(Locale.ROOT));
		return indexed == null ? -1 : indexed;
	}

	/**
	 * The card for the item called {@code name}, or null when no item has that name ({@link #idOf} gives -1). The card's
	 * price is the item manager's, which is 0 for an item that has none, and its drops are the sources {@link
	 * DropRates#lookup} gives for the name, of which the card shows four and counts the rest, or none when there is no
	 * table.
	 *
	 * <p>Choice: a null name gives no card, as an unknown one does.
	 */
	HoverCard forName(String name, int quantity, String plainLine, int start, int end)
	{
		final int id = idOf(name);
		if (id < 0)
		{
			return null;
		}
		final long price = itemManager.getItemPrice(id);
		final int alch = itemManager.getItemComposition(id).getHaPrice();
		return new ItemCard(id, name, quantity, price, alch, plainLine, start, end, sources(name));
	}

	/**
	 * The rate of the first source the table gives for the name, as the table writes it ("1/4000"), or an empty text when
	 * the table has not loaded, does not hold the name, or has nothing for it. It reads the sources the way {@link
	 * #forName} does, so the name's case counts the same; a pet's card asks it for the pet's own rate.
	 */
	String rateOf(String name)
	{
		final List<DropRates.DropSource> found = sources(name);
		return found.isEmpty() ? "" : found.get(0).rate;
	}

	/**
	 * The sources of the item, the table's list, or an empty one.
	 *
	 * <p>Choice: a table that has not loaded is not asked, so a card made in the first second after start-up is the card of
	 * lot 1.
	 */
	private List<DropRates.DropSource> sources(String name)
	{
		if (dropRates == null || !dropRates.loaded())
		{
			return Collections.emptyList();
		}
		return dropRates.lookup(name);
	}
}

package com.clanhub;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

/**
 * The names of every item in the game, lowercase, with each name's item id: the item cards' way to an id the price list
 * lacks (a new item, a pet). The game has tens of thousands of items and reading them all at once would stall a frame,
 * so the plugin builds the index a slice at a time, {@link #buildSome} on each game tick, until every id has been read.
 * Every real item is kept, tradeable or not: not a noted copy, not a placeholder, not "null", not a name under five
 * characters. It is read and built on the client thread, the caller's, so it is not synchronized.
 */
final class ItemNameIndex
{
	/** The shortest name kept, so "bow" never matches and "bones" does. */
	private static final int MIN_LENGTH = 5;

	/** The item id by lowercase name; the first id seen for a name stays. */
	private final Map<String, Integer> ids = new HashMap<>();
	/** The next item id to read. */
	int next;
	/** The client's item count as {@link #buildSome} last read it; -1 before the first call. */
	private int total = -1;

	/**
	 * Reads the item ids from {@link #next} up to {@code count} of them, never past the client's item count, and keeps
	 * the items that pass: not a noted item, not a placeholder, a name that is not "null" and has five characters or
	 * more. The first id seen for a lowercase name stays.
	 *
	 * <p>Choice: the item count is read on every call, so a call after the index is complete reads nothing; the index is
	 * not complete before its first call, whatever the item count. An item that cannot be traded or alched stays in:
	 * a pet and the other untradeables have no price, but a card needs their ids, for their pictures and their names.
	 */
	void buildSome(Client client, ItemManager itemManager, int count)
	{
		total = client.getItemCount();
		final int stop = (int) Math.min((long) next + count, total);
		for (; next < stop; next++)
		{
			final ItemComposition composition = itemManager.getItemComposition(next);
			if (composition != null && keeps(composition))
			{
				add(next, composition.getName());
			}
		}
	}

	/** Stores a name with its id, unless the lowercase name is already there, in which case the first one stays. */
	void add(int id, String name)
	{
		final String lower = name.toLowerCase(Locale.ROOT);
		if (idOf(lower) == null)
		{
			ids.put(lower, id);
		}
	}

	/** Whether every item id up to the client's item count has been read. */
	boolean complete()
	{
		return total >= 0 && next >= total;
	}

	/** How many names the index holds. */
	int size()
	{
		return ids.size();
	}

	/** The item id for a lowercase name, or null when the index does not know it. */
	Integer idOf(String lowercaseName)
	{
		return ids.get(lowercaseName);
	}

	/** Whether an item is one the index keeps. */
	private static boolean keeps(ItemComposition composition)
	{
		final String name = composition.getName();
		return composition.getNote() == -1
			&& composition.getPlaceholderTemplateId() == -1
			&& name != null
			&& name.length() >= MIN_LENGTH
			&& !"null".equalsIgnoreCase(name);
	}
}

package com.clanhub;

import java.util.List;
import net.runelite.api.ChatMessageType;

/**
 * Reads one chat line for the cards it holds. The plugin keeps a list of readers and asks each of them about every
 * chat message; a later lot adds a reader of its own and one line to that list.
 */
interface LineReader
{
	/**
	 * The cards the line holds, in the order their words stand in it; an empty list when it holds nothing. {@code message}
	 * is the chat text as the game sends it, tags and all.
	 */
	List<HoverCard> read(ChatMessageType type, String message);
}

package com.clanhub;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

/**
 * The sidebar button's icon, 16 x 16 px: the 2hBuilds coin top-left ({@link CoinGlyph}) and the plugin's own
 * picture clear of the coin. The picture is a strip of the chatbox across the bottom, its clan chat line with one
 * word of it lit in the hover blue and the arrow cursor's tip on that word, and the card standing above it in the
 * right-hand column with a row of air between. It is sheet 14's number 19 of {@code docs/pictures}, picked
 * 2026-10-08. Drawn in code, so it needs no image file.
 */
public final class NavIcon
{
	/** The sidebar icon size. */
	public static final int SIZE = 16;

	/** The picture's colours: the chatbox's parchment, the clan's dark blue, the hover blue, white and the ink. */
	private static final int PARCHMENT = new Color(205, 190, 158).getRGB();
	private static final int CLAN = new Color(0, 0, 176).getRGB();
	private static final int HOVER = new Color(59, 130, 246).getRGB();
	private static final int WHITE = new Color(240, 240, 240).getRGB();
	private static final int INK = new Color(22, 22, 26).getRGB();

	/**
	 * The picture, one character a pixel, sixteen rows of sixteen: P parchment, C the clan's blue, B the hover blue,
	 * W white, I ink, '.' nothing (the sidebar's own grey shows).
	 */
	private static final String[] PICTURE = {
		"................",
		"...........BBBB.",
		"..........BBBBBB",
		"..........WWWWWW",
		"..........WIIIIW",
		"..........WWWWWW",
		"..........WIIIWW",
		"..........WWWWWW",
		"...........WWWW.",
		"................",
		"PPPPPPPPPPPIIIPP",
		"PCCCCCCCCBBIWIIP",
		"PPPPPPPPPPPIWWII",
		"...........IWWWI",
		"...........IWWWW",
		"...........IWIWI",
	};

	private NavIcon()
	{
	}

	/** A new 16 x 16 ARGB image of the icon. */
	public static BufferedImage create()
	{
		final BufferedImage img = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			CoinGlyph.paint(g);
		}
		finally
		{
			g.dispose();
		}
		for (int y = 0; y < SIZE; y++)
		{
			for (int x = 0; x < SIZE; x++)
			{
				final int argb = colour(PICTURE[y].charAt(x));
				if (argb != 0)
				{
					img.setRGB(x, y, argb);
				}
			}
		}
		return img;
	}

	/** The opaque ARGB value a picture character stands for, or 0 for nothing. */
	private static int colour(char c)
	{
		switch (c)
		{
			case 'P':
				return PARCHMENT;
			case 'C':
				return CLAN;
			case 'B':
				return HOVER;
			case 'W':
				return WHITE;
			case 'I':
				return INK;
			default:
				return 0;
		}
	}
}

package com.clanhub;

import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;

/**
 * The reader of the player's own game lines about an item: a valuable drop, an untradeable drop and a new collection log
 * item. The sentences are the game's own and are read case-sensitively from the start of the line, once the tags are
 * stripped; {@link ItemCards} makes the card, so a line gives one card, or none when it is another line or names no item
 * the item manager knows.
 */
final class OwnLineReader implements LineReader
{
	/** "Valuable drop: 10 x Black knife (4,600 coins)": the quantity if any, the name, the value. */
	private static final Pattern VALUABLE = Pattern.compile("^Valuable drop: (?:(\\d+) x )?(.+?) \\((.+?) coins?\\)");
	/** "Untradeable drop: Pet snakeling": the quantity if any, the name, the value if any. */
	private static final Pattern UNTRADEABLE = Pattern.compile(
		"^Untradeable drop: (?:(\\d+) x )?(.+?)(?: \\((.+?) coins?\\))?$");
	/** "New item added to your collection log: Abyssal whip": the name. */
	private static final Pattern COLLECTION_LOG = Pattern.compile("^New item added to your collection log: (.+)$");

	private final ItemCards itemCards;

	OwnLineReader(ItemCards itemCards)
	{
		this.itemCards = itemCards;
	}

	/**
	 * The card for the item an own game line names, or none; only {@code GAMEMESSAGE} lines are read. The quantity is 1
	 * unless the line says "10 x".
	 *
	 * <p>Choice: a quantity too large for an int gives no card, as in {@link BroadcastLine}.
	 */
	@Override
	public List<HoverCard> read(ChatMessageType type, String message)
	{
		if (message == null || type != ChatMessageType.GAMEMESSAGE)
		{
			return Collections.emptyList();
		}
		final String plain = ChatText.plain(message);
		Matcher found = VALUABLE.matcher(plain);
		if (!found.find())
		{
			found = UNTRADEABLE.matcher(plain);
			if (!found.find())
			{
				found = COLLECTION_LOG.matcher(plain);
				return found.find() ? one(found, 1, 1, plain) : Collections.<HoverCard>emptyList();
			}
		}
		final String quantity = found.group(1);
		if (quantity == null)
		{
			return one(found, 2, 1, plain);
		}
		try
		{
			return one(found, 2, Integer.parseInt(quantity), plain);
		}
		catch (NumberFormatException e)
		{
			return Collections.emptyList();
		}
	}

	/** The one card for the match's name group, or an empty list when the item manager makes none. */
	private List<HoverCard> one(Matcher found, int nameGroup, int quantity, String plain)
	{
		final HoverCard card = itemCards.forName(found.group(nameGroup), quantity, plain, found.start(nameGroup),
			found.end(nameGroup));
		return card == null ? Collections.<HoverCard>emptyList() : Collections.singletonList(card);
	}
}

